import{_ as t,o as s,c as i,a2 as a}from"./chunks/framework.DNL3hc5c.js";const h=JSON.parse('{"title":"Registries and Dictionaries","description":"","frontmatter":{},"headers":[],"relativePath":"doc/3-extending-tempo/tempo.registry.md","filePath":"doc/3-extending-tempo/tempo.registry.md"}'),o={name:"doc/3-extending-tempo/tempo.registry.md"};function d(r,e,n,l,c,p){return s(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="registries-and-dictionaries" tabindex="-1">Registries and Dictionaries <a class="header-anchor" href="#registries-and-dictionaries" aria-label="Permalink to &quot;Registries and Dictionaries&quot;">​</a></h1><p>Tempo uses internal dictionaries—called <strong>Registries</strong>—to map string keys to values, functions, or formats. This is how Tempo resolves timezone abbreviations like <code>EST</code>, parses custom month layouts, and translates numbers to words.</p><p>By standardizing these data stores under the <code>registry</code> namespace, you can deeply customize how Tempo parses, formats, and understands regional values.</p><h2 id="accessing-registries" tabindex="-1">Accessing Registries <a class="header-anchor" href="#accessing-registries" aria-label="Permalink to &quot;Accessing Registries&quot;">​</a></h2><p>You can access active registries using the static <code>Tempo.registry</code> getter. These objects are <strong>Read-Only Proxies</strong>.</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { Tempo } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@magmacomputing/tempo&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Tempo.registry.formats);</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// { &#39;{iso}&#39;: &#39;{yyyy}-{mm}-{dd}T{hh}:{mi}:{ss}&#39;, ... }</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Because these registries are frozen proxies, attempting to mutate them directly (e.g., <code>Tempo.registry.formats.custom = &#39;...&#39;</code>) will throw an error. This guarantees that internal caches and parser guards remain synchronized.</p></div><p>To add or override values, you must use <code>Tempo.use()</code> or <code>Tempo.init()</code>:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Tempo.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  registry: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    formats: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      custom: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;{yyyy}!!{mm}!!{dd}&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><hr><h2 id="📅-timezone-registry" tabindex="-1">📅 TIMEZONE Registry <a class="header-anchor" href="#📅-timezone-registry" aria-label="Permalink to &quot;📅 TIMEZONE Registry&quot;">​</a></h2><p>Tempo includes a built-in registry of common timezone abbreviations. <strong>Most regional aliases map to DST-aware regional IANA zones, not fixed UTC offsets.</strong> For example, both <code>est</code> and <code>edt</code> map to <code>America/New_York</code>, which means dates parsed during summer months will automatically adjust to Eastern Daylight Time (<code>-04:00</code>), whereas <code>gmt</code> and <code>utc</code> map to fixed <code>UTC</code> (<code>+00:00</code>). If your application requires a constant, non-shifting offset year-round (e.g. strict UTC-5 without Daylight Saving adjustments), use an explicit fixed offset like <code>&quot;-05:00&quot;</code> or <code>&#39;Etc/GMT+5&#39;</code> instead of a regional abbreviation.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Alias</th><th style="text-align:left;">IANA Identifier</th></tr></thead><tbody><tr><td style="text-align:left;"><code>utc</code>/ <code>gmt</code></td><td style="text-align:left;"><code>UTC</code></td></tr><tr><td style="text-align:left;"><code>est</code> / <code>edt</code></td><td style="text-align:left;"><code>America/New_York</code></td></tr><tr><td style="text-align:left;"><code>cst</code> / <code>cdt</code></td><td style="text-align:left;"><code>America/Chicago</code></td></tr><tr><td style="text-align:left;"><code>mst</code> / <code>mdt</code></td><td style="text-align:left;"><code>America/Denver</code></td></tr><tr><td style="text-align:left;"><code>pst</code> / <code>pdt</code></td><td style="text-align:left;"><code>America/Los_Angeles</code></td></tr><tr><td style="text-align:left;"><code>aest</code> / <code>aedt</code></td><td style="text-align:left;"><code>Australia/Sydney</code></td></tr><tr><td style="text-align:left;"><code>acst</code> / <code>acdt</code></td><td style="text-align:left;"><code>Australia/Adelaide</code></td></tr><tr><td style="text-align:left;"><code>awst</code></td><td style="text-align:left;"><code>Australia/Perth</code></td></tr><tr><td style="text-align:left;"><code>nzt</code> / <code>nzst</code> / <code>nzdt</code></td><td style="text-align:left;"><code>Pacific/Auckland</code></td></tr><tr><td style="text-align:left;"><code>cet</code> / <code>cest</code></td><td style="text-align:left;"><code>Europe/Paris</code></td></tr><tr><td style="text-align:left;"><code>eet</code> / <code>eest</code></td><td style="text-align:left;"><code>Europe/Helsinki</code></td></tr><tr><td style="text-align:left;"><code>ist</code></td><td style="text-align:left;"><code>Asia/Kolkata</code></td></tr><tr><td style="text-align:left;"><code>npt</code></td><td style="text-align:left;"><code>Asia/Kathmandu</code></td></tr><tr><td style="text-align:left;"><code>jst</code></td><td style="text-align:left;"><code>Asia/Tokyo</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You can extend this list or override existing aliases using <code>Tempo.use({ registry: { timeZones: { ... } } })</code>.</p></div><hr><h2 id="other-internal-registries" tabindex="-1">Other Internal Registries <a class="header-anchor" href="#other-internal-registries" aria-label="Permalink to &quot;Other Internal Registries&quot;">​</a></h2><p>Tempo leverages several other internal data dictionaries to parse and format dates. The <code>formats</code> and <code>locales</code> dictionaries are organized under the <code>registry</code> configuration namespace.</p><ul><li><strong>Formats</strong>: Named format aliases used by the <code>format()</code> engine.</li><li><strong>Locales</strong>: Translation dictionaries used by the <code>:locale</code> format modifier.</li><li><strong>Events</strong>: Custom aliases mapped to specific dates.</li><li><strong>Periods</strong>: Custom aliases mapped to specific times.</li><li><strong>Snippets</strong>: Reusable Regex patterns mapped to variables for parsing.</li><li><strong>Layouts</strong>: Composed string patterns mapped to Regex logic for parsing.</li><li><strong>Numbers</strong>: Word-to-number dictionaries (e.g., <code>&quot;one&quot; -&gt; 1</code>).</li><li><strong>Ordinals</strong>: Word-to-ordinal offset dictionaries (e.g., <code>&quot;first&quot; -&gt; 1</code>, <code>&quot;last&quot; -&gt; -1</code>, <code>&quot;current&quot; -&gt; 0</code>).</li></ul><p><em>(Note: All dictionaries are consolidated into the <code>registry</code> namespace to separate data from behavior.)</em></p><h3 id="registry-merge-contracts" tabindex="-1">Registry Merge Contracts <a class="header-anchor" href="#registry-merge-contracts" aria-label="Permalink to &quot;Registry Merge Contracts&quot;">​</a></h3><p>The core internal <code>registryUpdate()</code> utility applies an <strong>additive-only</strong> merge strategy. It deeply merges new keys into the registries but safely preserves existing root keys (preventing accidental overrides of built-in definitions).</p><p>When you pass an options object to <code>Tempo.use()</code>, it acts differently depending on the data type:</p><ul><li><strong>Enum/Proxy-Backed Registries:</strong> For explicitly wrapped structures (like <code>formats</code> and <code>locales</code>), <code>Tempo.use()</code> can be used to forcefully shadow existing entries, making it the proper tool to change standard behaviors.</li><li><strong>General Registries:</strong> It does not provide a blanket, universal overwrite mechanism for the entire registry system.</li></ul>`,23)])])}const m=t(o,[["render",d]]);export{h as __pageData,m as default};
